const raw = $input.first().json.choices[0].message.content;
const article = JSON.parse(raw);

const today = new Date().toISOString().slice(0, 10);
const uniqueSlug = `${article.slug}-${today}`;
const esc = (s) => String(s || '').replace(/"/g, '\\"');
const tagsYaml = article.tags.map((t) => `"${esc(t)}"`).join(", ");

const faqItems = Array.isArray(article.faq) ? article.faq : [];
const faqYaml = faqItems.length
  ? `faq:\n${faqItems.map((f) => `  - question: "${esc(f.question)}"\n    answer: "${esc(f.answer)}"`).join('\n')}\n`
  : '';

const frontmatter = `---\ntitle: "${esc(article.title)}"\ndescription: "${esc(article.description)}"\ndate: "${today}"\ntags: [${tagsYaml}]\n${faqYaml}---\n\n`;

return [{
  json: {
    slug: uniqueSlug,
    title: article.title,
    path: `content/blog/${uniqueSlug}.md`,
    message: `Add article: ${article.title} (auto-generated)`,
    fileContent: frontmatter + article.body_markdown,
  },
}];
